export const cities={上海:[31.23,121.47],北京:[39.90,116.41],杭州:[30.27,120.15],广州:[23.13,113.26],深圳:[22.54,114.06],成都:[30.57,104.07],南京:[32.06,118.80],武汉:[30.59,114.31],重庆:[29.56,106.55],苏州:[31.30,120.58],西安:[34.34,108.94],天津:[39.08,117.20],长沙:[28.23,112.94],郑州:[34.75,113.63],青岛:[36.07,120.38],厦门:[24.48,118.09],福州:[26.07,119.30],济南:[36.65,117.12],合肥:[31.82,117.23],昆明:[25.04,102.72],南宁:[22.82,108.37],海口:[20.04,110.20],沈阳:[41.80,123.43],大连:[38.91,121.61],长春:[43.82,125.32],哈尔滨:[45.80,126.53],石家庄:[38.04,114.51],太原:[37.87,112.55],南昌:[28.68,115.86],贵阳:[26.65,106.63],兰州:[36.06,103.83],银川:[38.49,106.23],西宁:[36.62,101.78],乌鲁木齐:[43.83,87.62],拉萨:[29.65,91.14],呼和浩特:[40.84,111.75]};
export const today=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'}).format(new Date());
export function weatherName(c){return c===0?'晴':c<=3?'多云':c<=48?'雾':c<=67?'有雨':c<=77?'有雪':c<=82?'阵雨':c<=86?'阵雪':'雷雨'}
export async function getWeather(city){const coords=cities[city];if(!coords)throw Error('请选择支持的城市');const q=new URLSearchParams({latitude:coords[0],longitude:coords[1],timezone:'Asia/Shanghai',forecast_days:1,current:'temperature_2m,apparent_temperature,weather_code',hourly:'temperature_2m,apparent_temperature,precipitation_probability,weather_code,wind_speed_10m',daily:'temperature_2m_max,temperature_2m_min,weather_code,uv_index_max,wind_speed_10m_max,precipitation_probability_max'});const r=await fetch('https://api.open-meteo.com/v1/forecast?'+q,{signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error('天气更新失败');const d=await r.json();if(d.daily?.time?.[0]!==today()||!d.hourly?.time?.length||!Number.isFinite(d.daily.temperature_2m_max?.[0])||!d.current||!Number.isFinite(d.current.temperature_2m))throw Error('没有获取到今天的有效预报');return {...d,city,updated:Date.now()}}
export function advice(d,pref='normal',time='08:00'){const start=Number(time.split(':')[0]);const temps=d.hourly.apparent_temperature.slice(start,Math.min(24,start+3)).filter(Number.isFinite);if(!temps.length)throw Error('出门时段天气不完整');const t=Math.min(...temps)+(pref==='cold'?-3:pref==='hot'?3:0);const outfit=t>=28?'透气短袖 ＋ 轻薄长裤':t>=23?'短袖 ＋ 薄外套':t>=18?'长袖 ＋ 轻薄外套':t>=12?'针织衫 ＋ 防风外套':t>=5?'毛衣 ＋ 厚外套':'保暖内搭 ＋ 羽绒服';const rain=d.daily.precipitation_probability_max[0];const uv=d.daily.uv_index_max[0];const wind=d.daily.wind_speed_10m_max[0];const wet=d.hourly.precipitation_probability.map((v,i)=>v>=40?i:null).filter(x=>x!==null);const carry=[{icon:'umbrella',title:rain>=40?'折叠伞':'轻便雨具',desc:rain>=40?'今天可能有雨，放进包里更安心。':'降雨概率较低，长时间外出可备伞。'},{icon:'sun',title:uv>=3?'防晒用品':'日常防护',desc:uv>=3?'户外记得防晒，帽子也可以带上。':'紫外线较弱，按户外停留时间准备。'},{icon:wind>=29?'wind':'bottle',title:wind>=29?'防风外套':'随身水杯',desc:wind>=29?'风力较大，穿着防风外层。':'忙着赶路，也别忘了适时喝水。'}];return {outfit,t,rain,uv,wind,carry,tip:wet.length?`${wet[0]}:00${wet.length>1?'—'+wet.at(-1)+':00':''} 可能有雨，出门记得带伞。`:wind>=29?'今天风比较大，外套选防风一点的。':'今天降雨概率较低，出发前再留意天空变化。',detail:t>=23?'轻薄、透气为主，外套方便应对空调房和温差。':t>=12?'分层穿着更灵活，暖和时可以脱下外套。':'优先保暖，注意手脚和颈部的防风。',body:`${d.city}，${weatherName(d.daily.weather_code[0])} ${Math.round(d.daily.temperature_2m_min[0])}～${Math.round(d.daily.temperature_2m_max[0])}℃。穿衣：${outfit}。${rain>=40?'带上折叠伞。':''}${uv>=3?'户外注意防晒。':''}${wind>=29?'注意防风。':''}`}}
